const policyBasePremium = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const quote = (step: QuoteStep): { premium: number } => {
  const basePremium = policyBasePremium(step.items);
  const withPolicyModifiers = basePremium * (1 + FIRST_INSURANCE_SURCHARGE);

  return { premium: withPolicyModifiers + PROCESSING_FEE };
};

